 actual=np.zeros_like(processed);assert lib.spectral_component_render(processed.ctypes.data,dry.ctypes.data,actual.ctypes.data,n,rate,pd);pred,extra=spectral_ms(processed,dry,rate,pd,cfg['parameters'],key_quadratic=cfg['key_quadratic'],key_slopes=cfg['key_slopes'],phase_angles=cfg['common_phase_radians'],hf_parameters=cfg['hf_matrix_parameters'],hf_anchors=cfg['hf_matrix_anchors_Hz'],upper_rolloff=cfg['upper_rolloff_Hz'],harmonic_gain=cfg['harmonic_gain_parameters'],gain_orders=cfg['harmonic_gain_orders'],hf_sigma=cfg['hf_mask_sigma'],phase_key_slopes=cfg['common_phase_key_slopes'],phase_key_quadratic=cfg['common_phase_key_quadratic'],core_anchors=cfg['anchors_Hz'],adaptive_dynamic=cfg['dynamic_harmonic_parameters'],adaptive_stereo=cfg['stereo_harmonic_parameters'],final_stereo_balance=cfg['final_stereo_balance']);err=float(np.max(abs(actual[extra:]-pred[:-extra])));np.testing.assert_allclose(actual[extra:],pred[:-extra],rtol=0,atol=2e-10)
